#include "field_thermal_stocks.hpp"
#include "chem_v8_fixture.hpp"
#include "raikou/json.h"
#include <iostream>
#include <fstream>
namespace c=powerflow::common_conservation_v1;namespace h=hall_corrective_v3;namespace g=pf_gas_v1;namespace eh=electrode_heat_v2;using J=raikou::Json;
static unsigned checks=0;static void check(bool b,const char*s){++checks;if(!b)throw std::runtime_error(s);}template<class F>void refuses(F f,const char*s){bool got=false;try{f();}catch(const std::exception&){got=true;}check(got,s);}
int main(int argc,char**argv){try{
 if(argc!=2)throw std::runtime_error("TRACE");
 // Exact compensated quadratic: tiny low words remain visible despite rounded hi+lo.
 axial::Mesh synthetic(45,4,.009,1);axial::State z;z.E.assign(synthetic.ne,0);z.E_low=z.E;z.B.assign(synthetic.nb,0);z.B_low=z.B;synthetic.M.assign(synthetic.ne,0);synthetic.H.assign(synthetic.nb,0);
 synthetic.M[0]=2;z.E[0]=1;z.E_low[0]=std::ldexp(1.,-60);synthetic.H[0]=4;z.B[0]=3;z.B_low[0]=-.25;
 auto f=c::field_stock(synthetic,z);g::Exact expected;expected.add_product(1.,1.);expected.add_product(2.,std::ldexp(1.,-60));expected.add_product(std::ldexp(1.,-60),std::ldexp(1.,-60));check(f.electric_J==expected,"compensated cross terms exact");check(f.electric_J.value()==1&&!(f.electric_J==g::Exact{}),"small terms are retained");g::Exact mag;mag.add_product(2,2.75*2.75);check(mag==f.magnetic_J,"signed low word magnetic energy");
 auto bad=z;bad.E_low.pop_back();refuses([&]{c::field_stock(synthetic,bad);},"missing low words");bad=z;bad.E[0]=INFINITY;refuses([&]{c::field_stock(synthetic,bad);},"nonfinite fields");synthetic.M[0]=-1;refuses([&]{c::field_stock(synthetic,z);},"negative metric");synthetic.M[0]=std::numeric_limits<double>::denorm_min();refuses([&]{c::field_stock(synthetic,z);},"half metric underflow");synthetic.M[0]=3*std::numeric_limits<double>::denorm_min();refuses([&]{c::field_stock(synthetic,z);},"inexact subnormal half metric");
 auto law=eh::conditional_ss304_v2(ss304v2::Qualification::evaluated_solid_1500,ss304::DensityConvention::fixed_reference_volume_cp_as_cv_approximation,8000.,eh::material_headers_sha256);
 for(auto shape:{std::pair{8,2},std::pair{25,1}}){eh::Geometry geometry;geometry.nx=shape.first;geometry.ny=shape.second;geometry.height=.00625;geometry.electrode="conditional304";geometry.revision="manufactured-stock-control";
  eh::Coupler thermal(geometry,law,{},300,"manufactured-stock");mfem::FunctionCoefficient profile([](const mfem::Vector&x){return 400.+20000.*x[0]+1000.*x[1];});thermal.initialize_temperature(profile,"manufactured-nonuniform-temperature");
  auto candidate=thermal.state();for(std::size_t i=0;i<candidate.T.size();++i)candidate.T[i]+=.025*(1+i%3);auto stock=c::thermal_slice_stock(thermal,candidate);check(c::bits(stock.accepted_ordered_J,thermal.stored_energy_J()),"actual accepted thermal operation order");check(stock.after_J.value()>stock.before_J.value()&&stock.stable_delta_J.value()>0,"nonuniform real-material thermal energy");check(stock.nodes==std::size_t((shape.first+1)*(shape.second+1)),"nodal completeness");auto equal=c::thermal_slice_stock(thermal,thermal.state());check(c::difference(equal.after_J,equal.before_J).zero()&&equal.stable_delta_J.zero(),"unchanged thermal exact zero");
  auto short_state=candidate;short_state.T.pop_back();refuses([&]{c::thermal_slice_stock(thermal,short_state);},"candidate shape");auto hot=candidate;hot.T[0]=1500.1;refuses([&]{c::thermal_slice_stock(thermal,hot);},"material range not extrapolated");
 }
 const auto options=chemfix::options();auto model=std::make_shared<h::Model>(h::MeshSpec{},argv[1]);auto seed=model->dc_seed();const auto&mesh=model->mesh();h::ChargeLedger charge;charge.particles=h::charge_of_census(mesh,options,{});charge.conductor_C.resize(mesh.nn);charge.exterior_C.resize(mesh.nn);charge.conductor_declaration=chemfix::sha("independent-stock/manufactured-dc-conductor");charge.exterior_declaration=chemfix::sha("independent-stock/manufactured-dc-exterior");const auto Q=h::field_charge(mesh,seed);for(int k=0;k<mesh.nn;++k){if(mesh.node_body[k]>=0||mesh.short_node[k])charge.conductor_C[k]=Q[k];else if(mesh.outer_node[k])charge.exterior_C[k]=Q[k];}
 h::Owner owner(model,seed,charge,options,{});const auto before_field=owner.field_sha256(),before_heat=owner.heat_sha256();const double dt=1e-14;auto proposal=owner.prepare_vacuum(dt);check(owner.preflight_field_heat(proposal),"actual Hall vacuum proposal");const auto assessment=c::field_thermal_assessment(owner,proposal,dt);check(owner.field_sha256()==before_field&&owner.heat_sha256()==before_heat,"read-only stock assessment");check(assessment.thermal_slices==owner.thermal().slices()&&assessment.thermal_nodes>0,"all actual Hall thermal slices");
 auto residual=assessment.field_delta_J;residual.merge(assessment.thermal_stable_delta_J);residual.merge(assessment.outer_loss_J);residual.merge(assessment.outer_input_J,1);residual.merge(assessment.circuit_input_J,1);
 const auto&r=proposal.field_receipt();const double activity=std::abs(assessment.field_delta_J.value())+std::abs(assessment.thermal_stable_delta_J.value())+std::abs(assessment.outer_loss_J.value())+std::abs(assessment.outer_input_J.value())+std::abs(assessment.circuit_input_J.value());const double bound=2e-20+1e-10*activity+proposal.heat().roundoff_bound_J;
 check(std::abs(residual.value())<=bound,"independent stock residual within unchanged component tolerance");check(std::abs(assessment.circuit_input_J.value()-r.circuit_work_J)<=1e-14*std::abs(r.circuit_work_J),"actual midpoint drive operands");check(std::abs(assessment.outer_loss_J.value()-r.outer_loss_J)<=1e-14*std::abs(r.outer_loss_J)+1e-300,"actual outer flux operands");
 refuses([&]{c::field_thermal_assessment(owner,proposal,2*dt);},"wrong candidate interval");
 J result={{"passed",true},{"controls",checks},{"actual_Hall_thermal_nodes",assessment.thermal_nodes},{"actual_Hall_thermal_slices",assessment.thermal_slices},{"independent_field_delta_J",assessment.field_delta_J.value()},{"independent_thermal_delta_J",assessment.thermal_delta_J.value()},{"independent_thermal_stable_delta_J",assessment.thermal_stable_delta_J.value()},{"thermal_reference_rounding_J",assessment.thermal_reference_rounding_J.value()},{"independent_residual_J",residual.value()},{"unchanged_bound_J",bound},{"full_system_qualified",false},{"scope","independent field/thermal stocks and terminal operands; full particle/source/gas integration pending"}};std::cout<<result.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
